private val worker = HandlerThread("worker").apply { start() }
private val handler = Handler(worker.looper)

fun enqueue(job: Runnable) {
    handler.post(job)                    // serialized: one job at a time
}

fun cancelPending() {
    handler.removeCallbacksAndMessages(null)   // the leak-killer for delayed posts
}

override fun onDestroy() {
    worker.quitSafely()                  // drains, then stops the loop
    super.onDestroy()
}

