data class User(val id: String, val name: String) : Parcelable {
    constructor(parcel: Parcel) : this(
        parcel.readString()!!,
        parcel.readString()!!
    )

    override fun writeToParcel(dest: Parcel, flags: Int) {
        dest.writeString(id)
        dest.writeString(name)
    }

    override fun describeContents(): Int = 0

    companion object CREATOR : Parcelable.Creator<User> {
        override fun createFromParcel(parcel: Parcel): User = User(parcel)
        override fun newArray(size: Int): Array<User?> = arrayOfNulls(size)
    }
}

// Test: round-trip through a parcel keeps every field
val inParcel = Parcel.obtain()
val original = User("u1", "Ada")
original.writeToParcel(inParcel, 0)
inParcel.setDataPosition(0)
val restored = User.CREATOR.createFromParcel(inParcel)
check(restored == original)

// CHURN: a new array per item, per scroll frame
fun renderChurn(items: List<Item>) {
    items.forEach { draw(item -> FloatArray(16) { 0f }) }  // 16 floats each — wasteful
}

// FIX: reuse a scratch buffer owned by the render pass
class Renderer {
    private val scratch = FloatArray(16)
    fun render(items: List<Item>) {
        items.forEach { item ->
            item.toMatrix(scratch)   // writes into the same buffer, no new array
            draw(scratch)
        }
    }
}

class App : Application(), ComponentCallbacks2 {
    private val imageCache = LruCache<String, Bitmap>(32 * 1024 * 1024)

    override fun onTrimMemory(level: Int) {
        super.onTrimMemory(level)
        when {
            level >= ComponentCallbacks2.TRIM_MEMORY_RUNNING_LOW ->
                imageCache.evictAll()              // still foregrounded: shed caches
            level == ComponentCallbacks2.TRIM_MEMORY_UI_HIDDEN ->
                imageCache.evictAll()              // UI gone: drop UI-only state
            level >= ComponentCallbacks2.TRIM_MEMORY_BACKGROUND ->
                imageCache.evictAll()              // heading for the kill list
        }
    }
}

class Watcher {
    private val queue = ReferenceQueue<Any>()
    private val refs = mutableListOf<WeakReference<Any>>()

    fun watch(obj: Any) {
        refs += WeakReference(obj, queue)   // enqueued when obj is collected
    }

    fun gced(): Int {
        System.gc()
        Thread.sleep(100)
        var collected = 0
        while (queue.poll() != null) collected++
        return collected
    }
}

