class UploadService : Service() {
    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        // MUST come fast — ~10s window from startForegroundService
        val notification = buildNotification()
        startForeground(NOTIF_ID, notification)
        uploadWithProgress()
        stopSelf()
        return START_NOT_STICKY
    }
}

class DownloadWorker(context: Context, params: WorkerParameters) :
    CoroutineWorker(context, params) {

    override suspend fun doWork(): Result {
        val url = inputData.getString(KEY_URL) ?: return Result.failure()
        val file = File(applicationContext.filesDir, "download.bin")
        file.downloadFrom(url) { bytes -> setProgress(workDataOf(KEY_PROGRESS to bytes)) }
        return Result.success()
    }
}

val request = OneTimeWorkRequestBuilder<DownloadWorker>()
    .setInputData(workDataOf(KEY_URL to url))
    .setConstraints(Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build())
    .setProgressUpdateSpec(1000, TimeUnit.MILLISECONDS)
    .build()

// Runs as a user-initiated data transfer job — system-owned notification,
// exempt from quota, no foregroundServiceType or FOREGROUND_SERVICE permission.
WorkManager.getInstance(context).enqueue(request)
